=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters (default 4).
//
// Interface: interface_spec.md. Structure: microarchitecture.md.
// - State is one priority pointer `ptr`, $clog2(N) bits, reset to 0.
// - `grant` is combinational from `req` and `ptr`: the first requester with
//   `req` high at or after `ptr`, searching upwards and wrapping from N-1 to 0.
// - On a rising edge with a grant, `ptr` moves to one past the winner
//   (wrapping at N, not at a power of two). With no request it holds.
// - Reset is synchronous and active low; `grant` is not gated by reset.
// N must be 2 or more.

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    // Index constants N-1 and 1, built bit by bit so every width is exact.
    wire [PW-1:0] last_idx;
    wire [PW-1:0] one_idx;

    genvar b;
    generate
        for (b = 0; b < PW; b = b + 1) begin : g_const
            assign last_idx[b] = ((((N - 1) >> b) % 2) == 1);
            assign one_idx[b]  = (b == 0);
        end
    endgenerate

    reg  [PW-1:0] ptr;      // highest-priority requester this cycle
    reg  [PW-1:0] ptr_d;    // pointer for the next cycle
    reg  [PW-1:0] cand;     // search position
    reg  [PW-1:0] winner;   // index of the granted requester
    reg           found;    // a requester was granted this cycle
    integer       i;

    // Wrapping priority search from ptr, and the next pointer.
    always @* begin
        grant  = {N{1'b0}};
        winner = {PW{1'b0}};
        found  = 1'b0;
        cand   = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[cand]) begin
                found       = 1'b1;
                grant[cand] = 1'b1;
                winner      = cand;
            end
            if (cand == last_idx) begin
                cand = {PW{1'b0}};
            end else begin
                cand = cand + one_idx;
            end
        end
        if (!found) begin
            ptr_d = ptr;
        end else if (winner == last_idx) begin
            ptr_d = {PW{1'b0}};
        end else begin
            ptr_d = winner + one_idx;
        end
    end

    // Pointer register: synchronous active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_d;
        end
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume(!rst_n);

    always @(*) if (f_past_valid) begin
        assert(ptr <= last_idx);
        assert((grant & (grant - 1)) == 0);
        assert((grant & ~req) == 0);
        if (req != 0) assert(grant != 0);
    end

    always @(posedge clk) if (f_past_valid) begin
        if (!$past(rst_n))
            assert(ptr == 0);
        else if ($past(grant) != 0)
            assert(ptr == (($past(winner) == last_idx) ? 0 : $past(winner) + 1));
        else
            assert(ptr == $past(ptr));
    end

    genvar fj;
    generate
        for (fj = 0; fj < N; fj = fj + 1) begin : g_formal
            // circular distance from the pointer up to requester fj, and to the winner
            wire [31:0] f_dist  = (fj >= ptr) ? (fj - ptr) : (fj + N - ptr);
            wire [31:0] f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);
            reg  [31:0] f_wait  = 32'd0;
            always @(posedge clk) begin
                if (!rst_n)
                    f_wait <= 32'd0;
                else if (req[fj] && !grant[fj])
                    f_wait <= f_wait + 32'd1;
                else
                    f_wait <= 32'd0;
            end
            always @(*) if (f_past_valid) begin
                if ((grant != 0) && (f_dist < f_wdist)) assert(!req[fj]);
                assert(f_wait <= N - 1);
                assert(f_wait + f_dist <= N - 1);
                cover(grant[fj]);
                cover(f_wait == N - 1);
            end
        end
    endgenerate

    always @(*) if (f_past_valid) cover(req == {N{1'b1}});
    always @(posedge clk) if (f_past_valid)
        cover($past(rst_n) && ($past(grant) != 0) && ($past(winner) == last_idx));
`endif

endmodule
=== END FILE ===

=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb: self-checking testbench for rr_arbiter at N = 4 and N = 5.
//
// Both arbiters run side by side. Every cycle each grant is checked against
// a reference pointer model, for one-hot-or-zero, grant only to a requester,
// and work conservation; per-requester wait counters enforce the N-1 bound.
// Coverage counters fail the run if a case from interface_spec.md section 6
// was not reached. Failures use $error; the verdict is printed once before
// $finish.

module rr_arbiter_tb;

    reg        clk = 1'b0;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_arb4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_arb5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    always #5 clk = ~clk;

    integer        passed;
    integer        failed;
    integer        mptr4;           // reference pointer, N = 4
    integer        mptr5;           // reference pointer, N = 5
    integer        last_w4;         // last cycle's expected winner, -1 for none
    integer        last_w5;
    reg            model_valid;     // reference pointer known (after first reset edge)
    reg            released;        // reset has been released at least once
    integer        waitc     [0:8]; // wait counters: [0..3] N=4, [4..8] N=5
    integer        maxwait   [0:1];
    integer        cov_none  [0:1];
    integer        cov_all   [0:1];
    integer        cov_held  [0:1];
    integer        cov_fair  [0:1];
    integer        cov_rst   [0:1];
    integer        cov_alone [0:8];
    reg  [7:0]     prev_req  [0:1];
    reg  [31:0]    lfsr;
    reg  [8*64-1:0] nonce;
    integer        k;
    integer        j;

    // First requester with r high at or after p, wrapping at n; -1 if none.
    function integer rr_winner;
        input [7:0]   r;
        input integer n;
        input integer p;
        integer fk;
        integer fidx;
        begin
            rr_winner = -1;
            for (fk = n - 1; fk >= 0; fk = fk - 1) begin
                fidx = (p + fk) % n;
                if (r[fidx]) rr_winner = fidx;
            end
        end
    endfunction

    function [7:0] onehot8;
        input integer w;
        begin
            onehot8 = 8'd0;
            if (w >= 0) onehot8[w] = 1'b1;
        end
    endfunction

    function [7:0] ones8;
        input integer n;
        integer fq;
        begin
            ones8 = 8'd0;
            for (fq = 0; fq < n; fq = fq + 1) ones8[fq] = 1'b1;
        end
    endfunction

    task advance;
        begin
            lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
        end
    endtask

    // Check one arbiter for the current cycle and update its counters.
    task check_one;
        input integer  d;
        input integer  n;
        input integer  base;
        input [7:0]    r;
        input [7:0]    g;
        input integer  p;
        input          in_reset;
        output integer w;
        reg   [7:0]    exp_g;
        reg   [7:0]    me;
        integer        q;
        begin
            w     = rr_winner(r, n, p);
            exp_g = onehot8(w);

            if (g === exp_g) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d at %0t: req=%b ptr=%0d grant=%b, expected %b",
                       n, $time, r, p, g, exp_g);
            end

            if (((g & (g - 8'd1)) == 8'd0) && ((g & ~r) == 8'd0)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d at %0t: grant %b is not one-hot-or-zero within req %b",
                       n, $time, g, r);
            end

            if ((r == 8'd0) || (g != 8'd0)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d at %0t: req %b raised but nothing granted", n, $time, r);
            end

            for (q = 0; q < n; q = q + 1) begin
                me = onehot8(q);
                if (in_reset) begin
                    waitc[base + q] = 0;
                end else if (r[q] && !g[q]) begin
                    if ((waitc[base + q] > 0) && (((r ^ prev_req[d]) & ~me) != 8'd0))
                        cov_held[d] = cov_held[d] + 1;
                    waitc[base + q] = waitc[base + q] + 1;
                    if (waitc[base + q] > n - 1) begin
                        failed = failed + 1;
                        $error("N=%0d at %0t: requester %0d has waited %0d cycles",
                               n, $time, q, waitc[base + q]);
                    end else begin
                        passed = passed + 1;
                    end
                end else begin
                    if (g[q] && (waitc[base + q] == n - 1)) cov_fair[d] = cov_fair[d] + 1;
                    if (g[q] && (waitc[base + q] > maxwait[d])) maxwait[d] = waitc[base + q];
                    waitc[base + q] = 0;
                end
            end

            if (!in_reset) begin
                if (r == 8'd0) cov_none[d] = cov_none[d] + 1;
                if (r == ones8(n)) cov_all[d] = cov_all[d] + 1;
                for (q = 0; q < n; q = q + 1) begin
                    if ((r == onehot8(q)) && (g == r)) cov_alone[base + q] = cov_alone[base + q] + 1;
                end
            end else if (released && (r != 8'd0)) begin
                cov_rst[d] = cov_rst[d] + 1;
            end

            prev_req[d] = r;
        end
    endtask

    // One clock cycle: drive at the falling edge, check, then follow the
    // rising edge in the reference model.
    task step;
        input [3:0] r4;
        input [4:0] r5;
        input       rstv;
        integer     w4;
        integer     w5;
        begin
            @(negedge clk);
            rst_n = rstv;
            req4  = r4;
            req5  = r5;
            #1;
            if (model_valid) begin
                check_one(0, 4, 0, {4'd0, req4}, {4'd0, grant4}, mptr4, !rst_n, w4);
                check_one(1, 5, 4, {3'd0, req5}, {3'd0, grant5}, mptr5, !rst_n, w5);
            end else begin
                w4 = -1;
                w5 = -1;
            end
            last_w4 = w4;
            last_w5 = w5;
            @(posedge clk);
            if (!rst_n) begin
                mptr4       = 0;
                mptr5       = 0;
                model_valid = 1'b1;
            end else begin
                if (w4 >= 0) mptr4 = (w4 + 1) % 4;
                if (w5 >= 0) mptr5 = (w5 + 1) % 5;
                released = 1'b1;
            end
        end
    endtask

    task expect_index;
        input integer got;
        input integer want;
        input integer n;
        begin
            if (got == want) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("rotation N=%0d at %0t: granted %0d, expected %0d", n, $time, got, want);
            end
        end
    endtask

    task cov;
        input integer cnt;
        input integer kind;
        input integer n;
        input integer who;
        begin
            if (cnt > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                case (kind)
                    0: $error("coverage hole N=%0d: no-request cycles", n);
                    1: $error("coverage hole N=%0d: everyone requesting", n);
                    2: $error("coverage hole N=%0d: held request among changing others", n);
                    3: $error("coverage hole N=%0d: longest fair wait of N-1 cycles", n);
                    4: $error("coverage hole N=%0d: reset during traffic", n);
                    5: $error("coverage hole N=%0d: requester %0d alone", n, who);
                    default: $error("coverage hole N=%0d: kind %0d", n, kind);
                endcase
            end
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        mptr4       = 0;
        mptr5       = 0;
        last_w4     = -1;
        last_w5     = -1;
        model_valid = 1'b0;
        released    = 1'b0;
        rst_n       = 1'b0;
        req4        = 4'b0000;
        req5        = 5'b00000;
        lfsr        = 32'h1ACEB00C;
        nonce       = 0;
        for (j = 0; j < 9; j = j + 1) begin
            waitc[j]     = 0;
            cov_alone[j] = 0;
        end
        for (j = 0; j < 2; j = j + 1) begin
            maxwait[j]  = 0;
            cov_none[j] = 0;
            cov_all[j]  = 0;
            cov_held[j] = 0;
            cov_fair[j] = 0;
            cov_rst[j]  = 0;
            prev_req[j] = 8'd0;
        end

        // 1. Reset with no requests.
        for (k = 0; k < 3; k = k + 1) step(4'b0000, 5'b00000, 1'b0);

        // 2. Everyone requesting after reset: grants rotate 0, 1, ..., N-1, 0, ...
        for (k = 0; k < 15; k = k + 1) begin
            step(4'b1111, 5'b11111, 1'b1);
            expect_index(last_w4, k % 4, 4);
            expect_index(last_w5, k % 5, 5);
        end

        // 3. No requests.
        for (k = 0; k < 3; k = k + 1) step(4'b0000, 5'b00000, 1'b1);

        // 4. Each requester alone, two cycles each.
        for (k = 0; k < 5; k = k + 1) begin
            step(4'b0001 << k, 5'b00001 << k, 1'b1);
            step(4'b0001 << k, 5'b00001 << k, 1'b1);
        end

        // 5. Longest fair wait: requester 0 alone moves the pointer to 1,
        //    then everyone asks, so requester 0 waits N-1 cycles.
        step(4'b0001, 5'b00001, 1'b1);
        for (k = 0; k < 6; k = k + 1) step(4'b1111, 5'b11111, 1'b1);

        // 6. Requester 2 held while the others change at random.
        for (k = 0; k < 60; k = k + 1) begin
            advance;
            step(lfsr[3:0] | 4'b0100, lfsr[8:4] | 5'b00100, 1'b1);
        end

        // 7. Random subsets: requests dropped and raised.
        for (k = 0; k < 400; k = k + 1) begin
            advance;
            step(lfsr[3:0], lfsr[8:4], 1'b1);
        end

        // 8. Reset during traffic; the pointer stays at 0 during reset and the
        //    rotation restarts at 0 afterwards.
        for (k = 0; k < 6; k = k + 1) step(4'b1111, 5'b11111, 1'b1);
        advance;
        step(lfsr[3:0] | 4'b1000, lfsr[8:4] | 5'b10000, 1'b0);
        step(4'b0110, 5'b01100, 1'b0);
        step(4'b0110, 5'b01100, 1'b0);
        step(4'b1111, 5'b11111, 1'b0);
        for (k = 0; k < 10; k = k + 1) begin
            step(4'b1111, 5'b11111, 1'b1);
            expect_index(last_w4, k % 4, 4);
            expect_index(last_w5, k % 5, 5);
        end

        // 9. Sparse random traffic.
        for (k = 0; k < 300; k = k + 1) begin
            advance;
            step(lfsr[3:0] & lfsr[19:16], lfsr[8:4] & lfsr[28:24], 1'b1);
        end

        // Coverage: every case in the interface spec must have been reached.
        for (j = 0; j < 2; j = j + 1) begin
            cov(cov_none[j], 0, 4 + j, 0);
            cov(cov_all[j],  1, 4 + j, 0);
            cov(cov_held[j], 2, 4 + j, 0);
            cov(cov_fair[j], 3, 4 + j, 0);
            cov(cov_rst[j],  4, 4 + j, 0);
        end
        for (j = 0; j < 4; j = j + 1) cov(cov_alone[j], 5, 4, j);
        for (j = 0; j < 5; j = j + 1) cov(cov_alone[4 + j], 5, 5, j);

        $display("longest wait observed: N=4 %0d cycles, N=5 %0d cycles", maxwait[0], maxwait[1]);

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
